def check(ctx):
    d = ctx.depth()
    if d is None:
        return None
    pts = {}
    for uv in [[330, 70], [320, 60], [40, 80], [60, 120], [268, 238], [530, 185], [590, 40]]:
        z = float(d[uv[1], uv[0]])
        if z == z:
            p = ctx.deproject(uv[0], uv[1], z)
            pts[str(uv)] = [round(p["x"], 3), round(p["y"], 3), round(p["z"], 3)]
    ctx.state["pts"] = pts
    return None

def check(ctx):
    op = ctx.object_pose("u_green")
    if op is None:
        return None
    p = op["pose"]["position"]
    if "ref" not in ctx.state:
        ctx.state["ref"] = {"x": p["x"], "y": p["y"], "z": p["z"]}
        return None
    dd = ctx.dist(ctx.state["ref"], p)
    if dd > ctx.value("tol"):
        return {"value": dd, "detail": "u_green moved %.4f m from rest pose" % dd}
    return None

